class Solution {
  public int kthDigit(long k) {
    if (k <= 9) return (int) k;
    k -= 9;
    long first = 1;
    for (int d = 1; ; d++) {
      long blocks = 9 * first, blockDigits = 10L * (d + 1);
      long groupDigits = blocks * blockDigits;
      if (k > groupDigits) {
        k -= groupDigits;
        first *= 10;
        continue;
      }
      long b = first + (k - 1) / blockDigits, offset = (k - 1) % blockDigits;
      int j = (int) (offset / (d + 1)), pos = (int) (offset % (d + 1));
      long number = b % 2 == 0 ? 10 * b + j : 10 * b + 9 - j;
      return Long.toString(number).charAt(pos) - '0';
    }
  }
}
